package main

import "fmt"

func main() {
	var (
		dish  = "pancakes"
		vegan = true
	)
	var servings, minutes int = 4, 20
	chef, rating := "Sam", 4.5
	fmt.Println(dish, vegan, servings, minutes, chef, rating)
}

